# Tarea
Escribe la vista MIP del modelo del problema **CVRP (ruteo de vehículos con capacidad, flota libre)**, como DATOS (sin llamar a ningún solver). La vista heurística ya está escrita y aprobada contra los casos de prueba: NO la cambies ni la redefinas; tu módulo se concatena DESPUÉS de ella, así que puedes usar sus funciones (canonical, cost_terms…) directamente; no la importes (no es un módulo aparte).

# El problema
Hay un depósito (nodo 0) y clientes 1..n con coordenadas y demanda d[c] (`inst.demand[0] = 0`). Cada vehículo sale del depósito, visita una secuencia de clientes y vuelve al depósito; la suma de demandas de una ruta no puede superar `inst.capacity`. Cada cliente se visita exactamente una vez. La cantidad de vehículos es libre (no hay límite ni costo fijo por vehículo). Objetivo: minimizar la distancia euclidiana total recorrida (`inst.dist(i, j)`), incluidos los tramos desde y hacia el depósito. Una solución infactible debe tener un objetivo finito pero peor que cualquier factible (penalización).

# La instancia
```python
@dataclass(frozen=True)
class CVRPInstance:
    coords: tuple[tuple[float, float], ...]  # coords[0] = depósito
    demand: tuple[float, ...]  # demand[0] = 0
    capacity: float

    @property
    def n_customers(self) -> int:
        return len(self.coords) - 1

    @property
    def customers(self) -> range:
        return range(1, len(self.coords))

    def dist(self, i: int, j: int) -> float:
        (xi, yi), (xj, yj) = self.coords[i], self.coords[j]
        return math.hypot(xi - xj, yi - yj)

    @staticmethod
    def random(n_customers: int, rng: Random, route_size: float = 5.0, clustered: bool = False) -> "CVRPInstance":
        """Clientes en [0, 100]², depósito en el centro, demandas 1–10. La capacidad se fija
        para que una ruta atienda en promedio `route_size` clientes. `clustered=True` agrupa
        a los clientes en 3–5 centros (como las instancias C de Solomon / X de Uchoa)."""
        coords = [(50.0, 50.0)]
        if clustered:
            centers = [(rng.uniform(10, 90), rng.uniform(10, 90)) for _ in range(rng.randint(3, 5))]
            for _ in range(n_customers):
                cx, cy = rng.choice(centers)
                coords.append((min(100.0, max(0.0, rng.gauss(cx, 8))), min(100.0, max(0.0, rng.gauss(cy, 8)))))
        else:
            coords += [(rng.uniform(0, 100), rng.uniform(0, 100)) for _ in range(n_customers)]
        coords = [(round(x, 1), round(y, 1)) for x, y in coords]
        demand = [0.0] + [float(rng.randint(1, 10)) for _ in range(n_customers)]
        capacity = float(max(max(demand), round(route_size * sum(demand) / n_customers)))
        return CVRPInstance(tuple(coords), tuple(demand), capacity)

    def save(self, path: str) -> None:
        with open(path, "w") as f:
            f.write(f"{self.n_customers} {self.capacity}\n")
            for (x, y), d in zip(self.coords, self.demand):
                f.write(f"{x} {y} {d}\n")

    def to_text(self) -> str:
        """Formato de entrada (como un problema de Codeforces): `n Q`, luego n+1 líneas `x y d`
        (la primera es el depósito, con d = 0)."""
        lines = [f"{self.n_customers} {self.capacity:g}"]
        lines += [f"{x:g} {y:g} {d:g}" for (x, y), d in zip(self.coords, self.demand)]
        return "\n".join(lines) + "\n"

    @staticmethod
    def parse(text: str) -> "CVRPInstance":
        lines = [ln for ln in text.splitlines() if ln.strip()]
        n, cap = lines[0].split()
        rows = [tuple(map(float, ln.split())) for ln in lines[1:]]
        assert len(rows) == int(n) + 1, "se esperaban n+1 filas (depósito + clientes)"
        return CVRPInstance(tuple((x, y) for x, y, _ in rows), tuple(d for _, _, d in rows), float(cap))

    @staticmethod
    def load(path: str) -> "CVRPInstance":
        with open(path) as f:
            return CVRPInstance.parse(f.read())

```

# Vista heurística aprobada (ya definida antes de tu código)
```python
from __future__ import annotations

from random import Random
from typing import Any

from examples.cvrp.instance import CVRPInstance


def canonical(sol):
    routes = []
    for route in sol:
        if route:
            routes.append(tuple(int(c) for c in route))
    routes.sort(key=lambda r: r[0])
    return tuple(routes)


def trivial_solution(inst: CVRPInstance):
    return tuple((c,) for c in inst.customers)


def random_solution(inst: CVRPInstance, rng: Random):
    customers = list(inst.customers)
    rng.shuffle(customers)

    routes = []
    current = []
    current_load = 0.0
    for c in customers:
        d = inst.demand[c]
        if current and current_load + d > inst.capacity and rng.random() < 0.8:
            routes.append(tuple(current))
            current = [c]
            current_load = d
        else:
            current.append(c)
            current_load += d

    if current:
        routes.append(tuple(current))

    return canonical(routes)


def from_answer(inst: CVRPInstance, answer):
    return canonical(tuple(tuple(int(c) for c in route) for route in answer))


def violations(inst: CVRPInstance, sol) -> dict[str, float]:
    sol = canonical(sol)

    counts = [0] * (inst.n_customers + 1)
    for route in sol:
        for c in route:
            if 1 <= c <= inst.n_customers:
                counts[c] += 1
            else:
                counts[0] += 1  # out of range, counts as invalid extra visit

    visita = 0.0
    for c in inst.customers:
        visita += abs(counts[c] - 1)

    # Any invalid customer index is treated as a violation of visita as well
    visita += float(counts[0])

    capacidad = 0.0
    for route in sol:
        load = sum(inst.demand[c] for c in route if 1 <= c <= inst.n_customers)
        capacidad += max(0.0, load - inst.capacity)

    return {"visita": float(visita), "capacidad": float(capacidad)}


def cost_terms(inst: CVRPInstance, sol) -> dict[str, float]:
    sol = canonical(sol)

    distance = 0.0
    for route in sol:
        prev = 0
        for c in route:
            if 1 <= c <= inst.n_customers:
                distance += inst.dist(prev, c)
                prev = c
        distance += inst.dist(prev, 0)

    v = violations(inst, sol)
    penalty_scale = 1.0 + 1000.0 * (inst.n_customers + 1) * max(
        (inst.dist(i, j) for i in range(inst.n_customers + 1) for j in range(inst.n_customers + 1)),
        default=1.0,
    )
    penalized_distance = distance + penalty_scale * (v["visita"] + v["capacidad"])
    return {"distancia": float(penalized_distance)}

```

# Representación de la solución (obligatoria)
Tupla canónica de rutas: cada ruta, una tupla de clientes en orden de visita sin el depósito; las rutas vacías se omiten y las rutas se ordenan por su primer cliente (la usan los componentes heurísticos del problema).

# Funciones a escribir: la vista MIP como DATOS (el framework arma el modelo del solver y lo resuelve)

def variables(inst) -> dict[str, tuple[float, float, str]]: ...   # {nombre: (cota_inf, cota_sup, "binary" | "continuous")}
def structural_variables(inst) -> list[str]: ...    # las binarias que describen la solución (las demás son auxiliares)
def to_assignment(inst, sol) -> dict[str, float]: ...   # valor de TODAS las estructurales para `sol`
def aux_values(inst, sol) -> dict[str, float]: ...      # valor de TODAS las auxiliares en el punto de `sol` (p.ej. cargas, inventarios)
def from_assignment(inst, x) -> "sol": ...          # inversa: from_assignment(inst, to_assignment(inst, sol)) == sol (factibles)
def constraint_families(inst) -> dict[str, list[tuple[dict[str, float], str, float]]]: ...
    # {familia: [(coeficientes {variable: coef}, sentido "<=" | ">=" | "==", lado derecho), ...]}
    # El nombre de la familia (o su prefijo antes de un punto, p.ej. "visita.entrada") debe ser el nombre que
    # usa `violations`: se verificará que la familia del MIP se viola exactamente cuando violations la reporta.
def objective_terms(inst) -> dict[str, tuple[dict[str, float], float]]: ...
    # {término: (coeficientes, constante)} con los MISMOS nombres de término que cost_terms
def variable_groups(inst) -> dict[str, list[str]]: ...   # partición de structural_variables en bloques CHICOS
    # (al menos 4, ninguno con más de un tercio), según la estructura del problema: Fix-and-Optimize
    # libera de a 1 a 4 grupos por subproblema, y Relax-and-Fix fija un grupo por vez. Agrupa variables que
    # interactúan (elementos cercanos, el mismo período…): con todo lo demás fijo, liberar un grupo tiene que
    # dejar espacio para cambiar la solución


